    private void birthdayFieldKeyTyped(java.awt.event.KeyEvent evt) {//GEN-FIRST:event_birthdayFieldKeyTyped
        char c = evt.getKeyChar();
        if (Character.isISOControl(c)) {
            return;
        }
        if (!Character.isDigit(c)) {
            JOptionPane.showMessageDialog(
                    null,
                    "Please enter numbers only in Birthday",
                    "Error!",
                    JOptionPane.ERROR_MESSAGE
            );
            evt.consume();
        }
    }//GEN-LAST:event_birthdayFieldKeyTyped

