    /**
     * Displays today's date in the format: "Monday , 15 June 2026"
     */
    private void displayTodaysDate() {
        java.time.LocalDate today = java.time.LocalDate.now();
        String dayName = today.getDayOfWeek().getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
        String monthName = today.getMonth().getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
        String formatted = dayName + " , " + today.getDayOfMonth() + " " + monthName + " " + today.getYear();
        todaysDateValueLabel.setText(formatted);
    }

    private void clearAll() {
        birthdayField.setText("");
        birthmonthField.setText("");
        birthyearField.setText("");
        yearsField.setText("");
        monthsField.setText("");
        daysField.setText("");
        birthdayField.requestFocus();
    }

    /**
     * Calculates age using day/month borrowing logic.
     */
    private void calculateAge() {
        try {
            String dayStr = birthdayField.getText().trim();
            String monthStr = birthmonthField.getText().trim();
            String yearStr = birthyearField.getText().trim();

            if (dayStr.isEmpty() && monthStr.isEmpty() && yearStr.isEmpty()) {
                JOptionPane.showMessageDialog(
                        null,
                        "Kindly, fill in Birthday, Birthmonth and Birthyear to continue",
                        "Error!",
                        JOptionPane.ERROR_MESSAGE
                );
                return;
            }

            if (dayStr.isEmpty()) {
                JOptionPane.showMessageDialog(
                        null,
                        "Kindly, fill in Birthday to continue",
                        "Error!",
                        JOptionPane.ERROR_MESSAGE
                );
                return;
            }

            if (monthStr.isEmpty()) {
                JOptionPane.showMessageDialog(
                        null,
                        "Kindly, fill in Birthmonth to continue",
                        "Error!",
                        JOptionPane.ERROR_MESSAGE
                );
                return;
            }

            if (yearStr.isEmpty()) {
                JOptionPane.showMessageDialog(
                        null,
                        "Kindly, fill in Birthyear to continue",
                        "Error!",
                        JOptionPane.ERROR_MESSAGE
                );
                return;
            }

            int birthDay = Integer.parseInt(dayStr);
            int birthMonth = Integer.parseInt(monthStr);
            int birthYear = Integer.parseInt(yearStr);

            if (birthMonth < 1 || birthMonth > 12) {
                JOptionPane.showMessageDialog(
                        null,
                        "Invalid month entered. Month must be between 1 and 12.",
                        "Error!",
                        JOptionPane.ERROR_MESSAGE
                );
                return;
            }

            java.time.LocalDate today = java.time.LocalDate.now();

            if (birthYear < 0 || birthYear > today.getYear()) {
                JOptionPane.showMessageDialog(
                        null,
                        "Invalid year entered. Please input valid year",
                        "Error!",
                        JOptionPane.ERROR_MESSAGE
                );
                return;
            }

            java.time.YearMonth ym = java.time.YearMonth.of(birthYear, birthMonth);
            int daysInBirthMonth = ym.lengthOfMonth();

            if (birthDay < 1 || birthDay > daysInBirthMonth) {
                JOptionPane.showMessageDialog(
                        null,
                        "Invalid day entered for that month. Day must be between 1 and " + daysInBirthMonth + ".",
                        "Error!",
                        JOptionPane.ERROR_MESSAGE
                );
                return;
            }

            java.time.LocalDate birthDate = java.time.LocalDate.of(birthYear, birthMonth, birthDay);

            if (birthDate.isAfter(today)) {
                JOptionPane.showMessageDialog(
                        null,
                        "Birth date cannot be in the future.",
                        "Error!",
                        JOptionPane.ERROR_MESSAGE
                );
                return;
            }

            // Age calculation with day/month borrowing
            int currentYear = today.getYear();
            int currentMonth = today.getMonthValue();
            int currentDay = today.getDayOfMonth();

            if (currentDay < birthDay) {
                currentDay += daysInBirthMonth;
                currentMonth -= 1;
                if (currentMonth == 0) {
                    currentMonth = 12;
                    currentYear -= 1;
                }
            }

            if (currentMonth < birthMonth) {
                currentMonth += 12;
                currentYear -= 1;
            }

            int ageDays = currentDay - birthDay;
            int ageMonths = currentMonth - birthMonth;
            int ageYears = currentYear - birthYear;

            yearsField.setText(String.valueOf(ageYears));
            monthsField.setText(String.valueOf(ageMonths));
            daysField.setText(String.valueOf(ageDays));

        } catch (NumberFormatException ex) {
            JOptionPane.showMessageDialog(
                    null,
                    "Please enter numbers only in Birthday, Birthmonth and Birthyear",
                    "Error!",
                    JOptionPane.ERROR_MESSAGE
            );
        } catch (Exception ex) {
            JOptionPane.showMessageDialog(
                    null,
                    "Unexpected error occurred!",
                    "Error!",
                    JOptionPane.ERROR_MESSAGE
            );
        }
    }

